template <typename UnionPtrType>
RegionShapePtr RegionShape::Clone() const {
  switch (tag_) {
    case Tag::kRect:
      return NewRect(
          mojo::Clone(data_.rect));
    case Tag::kPolyline:
      return NewPolyline(
          mojo::Clone(data_.polyline));
  }
  return nullptr;
}

template <typename T,
          typename std::enable_if<std::is_same<
              T, RegionShape>::value>::type*>
bool RegionShape::Equals(const T& other) const {
  if (tag_ != other.which())
    return false;

  switch (tag_) {
    case Tag::kRect:
      return mojo::Equals(data_.rect, other.data_.rect);
    case Tag::kPolyline:
      return mojo::Equals(data_.polyline, other.data_.polyline);
  }

  return false;
}
